        var w = wire.Writer.init(a);
        errdefer w.deinit();
        try self.encodeInto(&w);
        return w.toOwnedSlice();
    }

    fn encodeInto(
        self: *const UninterpretedOption,
        w: *wire.Writer,
    ) wire.EncodeError!void {
        for (self.name) |v| {
            const mark = try w.beginLen(2);
            try v.encodeInto(w);
            try w.endLen(mark);
        }
        if (self.identifier_value) |v| {
            try w.writeBytes(3, v);
        }
        if (self.positive_int_value) |v| {
            try w.writeUint(4, v);
        }
        if (self.negative_int_value) |v| {
            try w.writeInt64(5, v);
        }
        if (self.double_value) |v| {
            try w.writeDouble(6, v);
        }
        if (self.string_value) |v| {
            try w.writeBytes(7, v);
        }
        if (self.aggregate_value) |v| {
            try w.writeBytes(8, v);
        }
    }
};

pub const UninterpretedOption_NamePart = struct {
    name_part: ?[]const u8 = null,
    is_extension: ?bool = null,

    pub fn decode(
        a: std.mem.Allocator,
        buf: []const u8,
    ) wire.DecodeError!*UninterpretedOption_NamePart {
        var r = wire.Reader.init(buf);
        return decodeReader(a, &r);
    }

    fn decodeReader(
        a: std.mem.Allocator,
        r: *wire.Reader,
    ) wire.DecodeError!*UninterpretedOption_NamePart {
        const msg = try a.create(UninterpretedOption_NamePart);
        msg.* = .{};
        while (try r.next()) |tag| switch (tag.field) {
            1 => {
                msg.name_part = try r.readBytes();
            },
            2 => {
                msg.is_extension = (try r.readVarint()) != 0;
            },
            else => try r.skip(tag.wire),
        };
        return msg;
    }

    pub fn encode(
        self: *const UninterpretedOption_NamePart,
        a: std.mem.Allocator,
    ) wire.EncodeError![]u8 {
        var w = wire.Writer.init(a);
        errdefer w.deinit();
        try self.encodeInto(&w);
        return w.toOwnedSlice();
    }

    fn encodeInto(
        self: *const UninterpretedOption_NamePart,
        w: *wire.Writer,
    ) wire.EncodeError!void {
        if (self.name_part) |v| {
            try w.writeBytes(1, v);
        }
        if (self.is_extension) |v| {
            try w.writeBool(2, v);
        }
    }
};

pub const Status = struct {
    code: ?i32 = null,
    message: ?[]const u8 = null,
    details: []*Any = &.{},

    pub fn decode(
        a: std.mem.Allocator,
        buf: []const u8,
    ) wire.DecodeError!*Status {
        var r = wire.Reader.init(buf);
        return decodeReader(a, &r);
    }

    fn decodeReader(
        a: std.mem.Allocator,
        r: *wire.Reader,
    ) wire.DecodeError!*Status {
        const msg = try a.create(Status);
        msg.* = .{};
        var list_details: std.ArrayList(*Any) = .empty;
        while (try r.next()) |tag| switch (tag.field) {
            1 => {
                msg.code = try r.readInt32();
            },
            2 => {
                msg.message = try r.readBytes();
            },
            3 => {
                var sub = try r.subReader();
                const v = try Any.decodeReader(a, &sub);
                try list_details.append(a, v);
            },
            else => try r.skip(tag.wire),
        };
        msg.details = try list_details.toOwnedSlice(a);
        return msg;
    }

    pub fn encode(
        self: *const Status,
        a: std.mem.Allocator,
    ) wire.EncodeError![]u8 {
        var w = wire.Writer.init(a);
        errdefer w.deinit();
        try self.encodeInto(&w);
        return w.toOwnedSlice();
    }

    fn encodeInto(
        self: *const Status,
        w: *wire.Writer,
    ) wire.EncodeError!void {
        if (self.code) |v| {
            try w.writeInt32(1, v);
        }
        if (self.message) |v| {
            try w.writeBytes(2, v);
        }
        for (self.details) |v| {
            const mark = try w.beginLen(3);
            try v.encodeInto(w);
            try w.endLen(mark);
        }
    }
};
